/**
 * FILE: concept_10_overflowing_dividend_chalice.js
 * THEME: Finance & Investment — Overflowing Dividend Chalice & Revenue Stream Pour
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phases for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Synchronized dividend liquid fill level (oscillates smoothly between 52% and 84% capacity)
  const fillNorm = 0.68 - 0.16 * Math.cos(p1) + 0.03 * Math.sin(p3);

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow/Bloom)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    glassTint: '#F8FAFC',
    rubyLight: '#FDA4AF',
    rubyMid: '#E11D48',
    rubyDark: '#BE123C',
    rubyDeep: '#881337',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    cyanLight: '#BAE6FD',
    cyanMid: '#38BDF8',
    cyanDark: '#0284C7',
    chestWood: '#B45309',
    chestWoodDark: '#78350F',
    orangeMid: '#FB923C'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // Helper: Gold Bullion Bar Trapezoid
  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }

  // Helper: 5-Point Trophy Star Vector
  function drawFivePointStar(centerX, centerY, outerR, innerR, fillCol) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI * 0.5 + (i * Math.PI) / 5;
      const r = i % 2 === 0 ? outerR : innerR;
      const sx = centerX + Math.cos(a) * r;
      const sy = centerY + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(sx, sy);
      else ctx.lineTo(sx, sy);
    }
    ctx.closePath();
    fillAndStroke(fillCol, COL.outline, 2.5 * s);
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING DIVIDEND BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Dividend Bridges in Lower Corridor (y = cy + 205*s)
  // Left gap: [cx - 285*s, cx - 220*s] | Right gap: [cx + 220*s, cx + 285*s]
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 282 * s, bridgeY);
  ctx.lineTo(cx - 224 * s, bridgeY);
  ctx.moveTo(cx + 224 * s, bridgeY);
  ctx.lineTo(cx + 282 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 276 * s + bProgL * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.rubyMid, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 230 * s + bProgR * 46 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: ANNUAL REVENUE & BULLISH DIVIDEND REPORT CARD
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 390 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  roundedRectPath(ltX + 26 * s, ltY + 25 * s, 96 * s, 32 * s, 8 * s);
  fillAndStroke(COL.rubyMid, COL.outline, 2.8 * s);
  drawUpArrow(ltX + 48 * s, ltY + 41 * s, 16 * s, COL.surfaceWhite, 3.5 * s);
  roundedRectPath(ltX + 68 * s, ltY + 36 * s, 42 * s, 10 * s, 5 * s);
  fillAndStroke(COL.surfaceWhite, null, 0);

  roundedRectPath(ltX + 140 * s, ltY + 35 * s, 165 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);

  ctx.beginPath();
  ctx.arc(ltX + ltW - 42 * s, ltY + 41 * s, 9 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // Inner Chart Frame (y: ltY + 80*s, height: 215*s)
  const cFrameX = ltX + 18 * s;
  const cFrameY = ltY + 80 * s;
  const cFrameW = ltW - 36 * s;
  const cFrameH = 215 * s;

  roundedRectPath(cFrameX, cFrameY, cFrameW, cFrameH, 14 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // Horizontal Grid Lines
  ctx.strokeStyle = COL.surfaceMuted;
  ctx.lineWidth = 2 * s;
  for (let g = 1; g <= 3; g++) {
    const gy = cFrameY + (cFrameH / 4) * g;
    ctx.beginPath();
    ctx.moveTo(cFrameX + 16 * s, gy);
    ctx.lineTo(cFrameX + cFrameW - 16 * s, gy);
    ctx.stroke();
  }

  // 5 Ascending Revenue Bars + Separated Upper Profit Curve
  const barCount = 5;
  const barW = 32 * s;
  const barSpacing = (cFrameW - 76 * s) / (barCount - 1);
  const barBottomY = cFrameY + cFrameH - 14 * s;
  const baseRevRatios = [0.24, 0.34, 0.44, 0.56, 0.70];
  const revNodes = [];

  for (let i = 0; i < barCount; i++) {
    const bCenterX = cFrameX + 38 * s + i * barSpacing;
    const mod = 0.05 * Math.sin(p2 - i * 0.75);
    const bh = (baseRevRatios[i] + mod) * (cFrameH - 52 * s);
    const by = barBottomY - bh;

    const barCol = i === 4 ? COL.rubyMid : (i >= 2 ? COL.goldMid : COL.emeraldMid);
    roundedRectPath(bCenterX - barW * 0.5, by, barW, bh, 7 * s);
    fillAndStroke(barCol, COL.outline, thinStrokeW);

    revNodes.push({ x: bCenterX, y: by - 26 * s });
  }

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = 4 * s;
  ctx.beginPath();
  for (let i = 0; i < revNodes.length; i++) {
    if (i === 0) ctx.moveTo(revNodes[i].x, revNodes[i].y);
    else ctx.lineTo(revNodes[i].x, revNodes[i].y);
  }
  ctx.stroke();

  for (let i = 0; i < revNodes.length; i++) {
    ctx.beginPath();
    ctx.arc(revNodes[i].x, revNodes[i].y, 7 * s, 0, tau);
    fillAndStroke(i === 4 ? COL.goldMid : COL.surfaceWhite, COL.outline, 2.8 * s);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: DIVIDEND PAYOUT ALLOCATION & TREASURE CHEST PEDESTAL
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 390 * s;
  const lbCardH = 190 * s;

  // 4A. Upper Dividend Payout Allocation Card
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Left Segmented Donut Ring inside Card
  const dCX = lbX + 80 * s;
  const dCY = lbY + lbCardH * 0.5;
  const dR = 52 * s;
  const dAngles = [0, tau * 0.44, tau * 0.78, tau];
  const dCols = [COL.rubyMid, COL.goldMid, COL.emeraldMid];

  for (let k = 0; k < 3; k++) {
    ctx.beginPath();
    ctx.moveTo(dCX, dCY);
    ctx.arc(dCX, dCY, dR, p1 + dAngles[k], p1 + dAngles[k + 1]);
    ctx.closePath();
    fillAndStroke(dCols[k], COL.outline, thinStrokeW);
  }
  ctx.beginPath();
  ctx.arc(dCX, dCY, 24 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Right 3 Payout Ratio Meters
  const mStartX = lbX + 156 * s;
  const mWidth = 210 * s;
  for (let m = 0; m < 3; m++) {
    const my = lbY + 34 * s + m * 48 * s;
    roundedRectPath(mStartX, my, 84 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(mStartX, my + 15 * s, mWidth, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const mFill = (0.58 + 0.28 * Math.sin(p2 + m * 1.15)) * (mWidth - 6 * s);
    roundedRectPath(mStartX + 3 * s, my + 18 * s, mFill, 12 * s, 6 * s);
    fillAndStroke(dCols[m], null, 0);
  }

  // 4B. Lower Treasure Vault Chest, Bullion & Coin Pedestal on baseLineY
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  // Column 1 (Left): Structured Flat Vector Treasure Chest filled with Gold & Ruby Gems
  // Center X = lbX + 86*s, width = 128*s -> spans [22, 150]
  const chestCX = lbX + 86 * s;
  const chestW = 128 * s;
  const chestBaseH = 48 * s;
  const chestX = chestCX - chestW * 0.5;
  const chestBaseY = pedLY - chestBaseH;

  // Open Upper Lid Dome at top of chest
  ctx.beginPath();
  ctx.moveTo(chestX + 4 * s, chestBaseY - 16 * s);
  ctx.quadraticCurveTo(chestCX, chestBaseY - 56 * s, chestX + chestW - 4 * s, chestBaseY - 16 * s);
  ctx.closePath();
  fillAndStroke(COL.chestWoodDark, COL.outline, strokeW);

  // Gold & Ruby Treasure Mound inside open chest (between lid and lower box)
  const gemOffsets = [-38, -19, 0, 19, 38];
  for (let g = 0; g < gemOffsets.length; g++) {
    const gx = chestCX + gemOffsets[g] * s;
    const gy = chestBaseY - (8 + (g % 2) * 5) * s;
    ctx.beginPath();
    ctx.arc(gx, gy, 13 * s, 0, tau);
    fillAndStroke(g === 2 ? COL.rubyMid : COL.goldMid, COL.outline, 2.8 * s);
  }

  // Chest Lower Box Body
  roundedRectPath(chestX, chestBaseY, chestW, chestBaseH, 8 * s);
  fillAndStroke(COL.chestWood, COL.outline, strokeW);

  // Gold Reinforcing Straps on Chest Box
  roundedRectPath(chestX + 16 * s, chestBaseY, 14 * s, chestBaseH, 3 * s);
  fillAndStroke(COL.goldMid, COL.outline, 2.8 * s);
  roundedRectPath(chestX + chestW - 30 * s, chestBaseY, 14 * s, chestBaseH, 3 * s);
  fillAndStroke(COL.goldMid, COL.outline, 2.8 * s);

  // Center Gold Lock Plate on Chest Box
  roundedRectPath(chestCX - 14 * s, chestBaseY - 4 * s, 28 * s, 24 * s, 6 * s);
  fillAndStroke(COL.goldLight, COL.outline, 2.8 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 220*s, spans [178, 262], 28*s clear gap!)
  const stackLCX = lbX + 220 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 84 * s, cH);
  }

  // Column 3 (Right): 2 Stacked Gold Bullion Bars (x center = lbX + 328*s, spans [272, 384], 10*s+ clear gap!)
  const bulLCX = lbX + 328 * s;
  drawBullionBar(bulLCX, pedLY, 112 * s, 36 * s);
  drawBullionBar(bulLCX, pedLY - 36 * s, 96 * s, 34 * s);

  // =========================================================================
  // 5. CENTER ZONE: OVERFLOWING DIVIDEND CHALICE & REVENUE STREAM POUR
  // Directly inspired by the wine/chalice glass with sloshing ruby liquid & top pour stream in reference video (01:00 - 01:08)
  // Goblet Center X: cx | Bowl Rim Y: cy - 175*s | Bowl Bottom Y: cy + 85*s
  // =========================================================================
  const cupFloatY = Math.sin(p2) * 3.5 * s;
  const bowlRimY = cy - 175 * s + cupFloatY;
  const bowlBotY = cy + 85 * s + cupFloatY;
  const bowlHalfW = 136 * s;
  const bowlBottomR = 124 * s;

  // 5A. Central Chalice Pedestal Platform on baseLineY (y: cy + 318*s to cy + 395*s)
  roundedRectPath(cx - 104 * s, cy + 318 * s, 208 * s, 42 * s, 10 * s);
  fillAndStroke(COL.slateMid, COL.outline, strokeW);

  roundedRectPath(cx - 158 * s, baseLineY - 38 * s, 316 * s, 38 * s, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  roundedRectPath(cx - 112 * s, baseLineY - 22 * s, 224 * s, 10 * s, 5 * s);
  fillAndStroke(COL.goldMid, null, 0);

  // 5B. Top Revenue Dispenser Nozzle & Continuous Pouring Ruby Stream
  // Dispenser sits at top center (y: cy - 380*s to cy - 332*s)
  const dispW = 148 * s;
  const dispH = 38 * s;
  const dispY = cy - 380 * s;
  roundedRectPath(cx - dispW * 0.5, dispY, dispW, dispH, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  // Gold Spout Collar below Dispenser
  const spoutW = 68 * s;
  const spoutH = 20 * s;
  const spoutY = dispY + dispH - 2 * s;
  roundedRectPath(cx - spoutW * 0.5, spoutY, spoutW, spoutH, 6 * s);
  fillAndStroke(COL.goldMid, COL.outline, strokeW);

  // Continuous Ruby-Crimson Revenue Stream pouring from Spout down into the Chalice Bowl
  // Stream sways subtly in sync with the sloshing wave inside the cup (like reference 01:01)
  const streamTopY = spoutY + spoutH - 2 * s;
  const streamEndY = bowlBotY - 35 * s;
  const streamSway = Math.sin(p2) * 8 * s;
  const streamTopHalfW = 15 * s;
  const streamMidHalfW = 11 * s;

  ctx.beginPath();
  ctx.moveTo(cx - streamTopHalfW, streamTopY);
  ctx.bezierCurveTo(
    cx - streamMidHalfW + streamSway * 0.4, (streamTopY + bowlRimY) * 0.5,
    cx - streamMidHalfW + streamSway, bowlRimY + 30 * s,
    cx - streamMidHalfW + streamSway * 0.8, streamEndY
  );
  ctx.lineTo(cx + streamMidHalfW + streamSway * 0.8, streamEndY);
  ctx.bezierCurveTo(
    cx + streamMidHalfW + streamSway, bowlRimY + 30 * s,
    cx + streamMidHalfW + streamSway * 0.4, (streamTopY + bowlRimY) * 0.5,
    cx + streamTopHalfW, streamTopY
  );
  ctx.closePath();
  fillAndStroke(COL.rubyMid, COL.outline, thinStrokeW);

  // Inner light ruby highlight ribbon along center of pouring stream
  ctx.strokeStyle = COL.rubyLight;
  ctx.lineWidth = 5 * s;
  ctx.beginPath();
  ctx.moveTo(cx, streamTopY + 8 * s);
  ctx.quadraticCurveTo(cx + streamSway * 0.6, bowlRimY, cx + streamSway * 0.8, streamEndY - 20 * s);
  ctx.stroke();

  // 5C. Chalice Stem, Gold Collar Node & Foot Base (y: bowlBotY to cy + 318*s)
  const footY = cy + 318 * s;
  const stemH = footY - bowlBotY;

  // Vertical Stem Pillar
  roundedRectPath(cx - 15 * s, bowlBotY - 6 * s, 30 * s, stemH + 8 * s, 8 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, strokeW);

  // Decorative Gold Collar Ring around Mid-Stem
  const collarMidY = bowlBotY + stemH * 0.45;
  roundedRectPath(cx - 34 * s, collarMidY - 12 * s, 68 * s, 24 * s, 12 * s);
  fillAndStroke(COL.goldMid, COL.outline, strokeW);

  // Flared Goblet Foot Base sitting on Central Pedestal
  ctx.beginPath();
  ctx.moveTo(cx - 88 * s, footY);
  ctx.quadraticCurveTo(cx - 64 * s, footY - 30 * s, cx - 22 * s, footY - 30 * s);
  ctx.lineTo(cx + 22 * s, footY - 30 * s);
  ctx.quadraticCurveTo(cx + 64 * s, footY - 30 * s, cx + 88 * s, footY);
  ctx.closePath();
  fillAndStroke(COL.goldMid, COL.outline, strokeW);

  // 5D. U-Shaped Chalice Bowl & Dynamic Sloshing Ruby Liquid
